def transform(grid):
    from collections import Counter
    import math
    h = len(grid); w = len(grid[0])
    def ent(vals):
        cnt = Counter(vals); n = len(vals)
        return -sum((v/n) * math.log2(v/n) for v in cnt.values())
    re = sum(ent(grid[r]) for r in range(h)) / h
    ce = sum(ent([grid[r][c] for r in range(h)]) for c in range(w)) / w
    if re <= ce:
        return [[Counter(grid[r]).most_common(1)[0][0]] * w for r in range(h)]
    out = [[0] * w for _ in range(h)]
    for c in range(w):
        m = Counter(grid[r][c] for r in range(h)).most_common(1)[0][0]
        for r in range(h):
            out[r][c] = m
    return out
